def normalize(relative, source, *, batch=True):
    if batch:source=batch_normalize(relative, source)
    boundary=BOUNDARIES.get(relative)
    if boundary is None:return source
    if relative=='src/game/remove_diagnostics.cpp':
        root_blocks=[
            ('std::string scene_owner,scene_record;', 'std::string scene_owner;'),
            ('        if(!saved.scene_record.empty())retained.back()["native_record_key"]=saved.scene_record;\n', '')]
        present=[source.count(added) for added,_ in root_blocks]
        if any(present):
            assert present==[1,1], "Root Scenery exact source boundary differs"
            for added,prior in root_blocks:source=source.replace(added,prior,1)
    if relative=='src/game/npc_probe.cpp':
        # The Gizmo reader uses the NativeOpen declaration beside its scene reader.
        added='#include "dungeon_scene_identity_runtime.h"\n#include "native_open_runtime.h"\n'
        if source.count(added)==1:
            source=source.replace(added,'#include "dungeon_scene_identity_runtime.h"\n',1)
    if hashlib.sha256(source.encode()).hexdigest()!=boundary['candidate_sha256']:
        raise AssertionError('Scene Scenery exact candidate source differs: '+relative)
    for addition,prior in boundary['blocks']:
        if source.count(addition)!=1:raise AssertionError('Scene Scenery exact additive boundary differs: '+relative)
        source=source.replace(addition,prior,1)
    if hashlib.sha256(source.encode()).hexdigest()!=boundary['before_sha256']:
        raise AssertionError('Scene Scenery normalization changed an unrelated original guard: '+relative)
    return source
